using System.Text.Json;
using ASPAssistant.Core.Models;

namespace ASPAssistant.Core.Data;

/// <summary>
/// Loads data/garrison_maps.json (cells, routes, camera corners) and data/garrison_map_refs.json
/// (recognition fingerprints, generated by build_garrison_map_refs.py).
/// </summary>
public static class GarrisonBoardStore
{
    public static async Task<GarrisonBoardData?> LoadAsync(string dataDirectory)
    {
        var mapsPath = Path.Combine(dataDirectory, "garrison_maps.json");
        if (!File.Exists(mapsPath)) return null;
        using var maps = JsonDocument.Parse(await File.ReadAllTextAsync(mapsPath));
        var refsPath = Path.Combine(dataDirectory, "garrison_map_refs.json");
        using var refs = File.Exists(refsPath) ? JsonDocument.Parse(await File.ReadAllTextAsync(refsPath)) : null;
        return Parse(maps.RootElement, refs?.RootElement);
    }

    public static GarrisonBoardData Parse(JsonElement maps, JsonElement? refs)
    {
        int firstColumn = maps.GetProperty("columns")[0].GetInt32();

        var cameras = new Dictionary<BoardCamera, BoardProjection>();
        foreach (var cam in maps.GetProperty("cameras").EnumerateObject())
        {
            if (!TryCamera(cam.Name, out var camera)) continue;
            var corners = cam.Value.EnumerateArray().Select(p =>
                ((p[0][0].GetDouble(), p[0][1].GetDouble()), (p[1][0].GetDouble(), p[1][1].GetDouble()))).ToList();
            cameras[camera] = new BoardProjection(corners);
        }

        var list = new List<GarrisonMap>();
        foreach (var m in maps.GetProperty("maps").EnumerateArray())
        {
            var rows = m.GetProperty("cells").EnumerateArray().Select(r => r.GetString() ?? "").ToList();
            int width = rows.Max(r => r.Length);
            var cells = new BoardCellType[rows.Count, width];
            for (int r = 0; r < rows.Count; r++)
                for (int c = 0; c < width; c++)
                    cells[r, c] = c < rows[r].Length ? CellType(rows[r][c]) : BoardCellType.Blocked;
            var routes = new List<IReadOnlyList<BoardCell>>();
            if (m.TryGetProperty("routes", out var rs))
                foreach (var route in rs.EnumerateArray())
                    routes.Add(route.GetProperty("cells").EnumerateArray()
                        .Select(c => new BoardCell(c[0].GetInt32(), c[1].GetInt32())).ToList());
            list.Add(new GarrisonMap(m.GetProperty("id").GetString() ?? "", m.GetProperty("name").GetString() ?? "",
                firstColumn, cells, routes));
        }

        var bench = maps.GetProperty("bench");
        var fingerprints = new Dictionary<string, IReadOnlyDictionary<BoardCamera, byte[][]>>();
        if (refs is { } r0 && r0.TryGetProperty("maps", out var refMaps))
            foreach (var map in refMaps.EnumerateObject())
            {
                var perCamera = new Dictionary<BoardCamera, byte[][]>();
                foreach (var cam in map.Value.EnumerateObject())
                    if (TryCamera(cam.Name, out var camera))
                        perCamera[camera] = cam.Value.EnumerateArray()
                            .Select(p => new[] { (byte)p[0].GetInt32(), (byte)p[1].GetInt32(), (byte)p[2].GetInt32() })
                            .ToArray();
                fingerprints[map.Name] = perCamera;
            }

        return new GarrisonBoardData
        {
            Cameras = cameras,
            Maps = list,
            Bench = (bench.GetProperty("row").GetInt32(), bench.GetProperty("columns")[0].GetInt32(),
                bench.GetProperty("columns")[1].GetInt32()),
            Fingerprints = fingerprints,
        };
    }

    private static bool TryCamera(string name, out BoardCamera camera)
    {
        camera = name == "expanded" ? BoardCamera.Expanded : BoardCamera.Collapsed;
        return name is "expanded" or "collapsed";
    }

    private static BoardCellType CellType(char c) => c switch
    {
        'G' => BoardCellType.Ground,
        'T' => BoardCellType.Special,
        'H' => BoardCellType.High,
        'D' => BoardCellType.Defense,
        'S' => BoardCellType.Spawn,
        _ => BoardCellType.Blocked,
    };
}
